create table if not exists profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, email text, role text default 'subscriber' check (role in ('subscriber','admin')), created_at timestamptz default now());
create table if not exists subscriptions (id bigint generated always as identity primary key,user_id uuid references profiles(id) on delete cascade,plan text check(plan in ('monthly','yearly')),status text default 'active',start_date date default current_date,renewal_date date);
create table if not exists golf_scores (id bigint generated always as identity primary key,user_id uuid references profiles(id) on delete cascade,score int check(score between 45 and 150),score_date date not null,created_at timestamptz default now(),unique(user_id,score_date));
create table if not exists charities (id bigint generated always as identity primary key,name text not null,description text,impact text,image_url text,is_featured boolean default false,created_at timestamptz default now());
create table if not exists charity_contributions (id bigint generated always as identity primary key,user_id uuid references profiles(id) on delete cascade,charity_id bigint references charities(id),percentage numeric default 10 check(percentage>=10 and percentage<=100),amount numeric default 0,created_at timestamptz default now());
create table if not exists draws (id bigint generated always as identity primary key,draw_date date unique not null,status text default 'draft',total_pool numeric default 0,number_3_pool numeric default 0,number_4_pool numeric default 0,number_5_pool numeric default 0,winning_numbers text);
create table if not exists winners (id bigint generated always as identity primary key,draw_id bigint references draws(id),user_id uuid references profiles(id),match_type text,amount numeric,verification_status text default 'pending',proof_url text,payment_status text default 'pending',created_at timestamptz default now());
insert into charities(name,description,impact,is_featured) values ('Fairway Futures Foundation','Creates access to golf, coaching and community programmes for young people.','Junior golf access',true),('Green Fairways Trust','Supports sustainable courses and local environmental projects.','Greener golf courses',false),('Golf For All','Makes golf accessible to underserved communities through equipment and coaching.','Inclusive golf',false) on conflict do nothing;
alter table profiles enable row level security; alter table subscriptions enable row level security; alter table golf_scores enable row level security; alter table charities enable row level security; alter table charity_contributions enable row level security;
create policy "public charities" on charities for select using (true);
create policy "own profile" on profiles for all using (auth.uid()=id) with check (auth.uid()=id);
create policy "own scores" on golf_scores for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "own subscription" on subscriptions for select using (auth.uid()=user_id);
create policy "own contributions" on charity_contributions for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email,full_name) values(new.id,new.email,new.raw_user_meta_data->>'full_name'); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
